from bisect import bisect_left
from typing import List

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        # keep original indices
        intervals = [(l, r, w, idx) for idx, (l, r, w) in enumerate(intervals)]
        intervals.sort(key=lambda x: x[0])  # sort by start
        starts = [iv[0] for iv in intervals]
        ends = [iv[1] for iv in intervals]
        # dp[i][k] -> (weight, indices list) for best using interval i as last, picking k intervals total (including i)
        dp_weight = [[-1] * 5 for _ in range(n)]
        dp_path = [[[] for _ in range(5)] for _ in range(n)]
        best_weight = [-1] * 5
        best_path = [[] for _ in range(5)]
        for i, (l, r, w, idx) in enumerate(intervals):
            # option of picking only this interval
            dp_weight[i][1] = w
            dp_path[i][1] = [idx]
            # find previous interval that does not overlap: end < l
            j = bisect_left(ends, l) - 1
            if j >= 0:
                for k in range(1, 4):
                    if dp_weight[j][k] != -1:
                        new_weight = dp_weight[j][k] + w
                        if new_weight > dp_weight[i][k+1]:
                            dp_weight[i][k+1] = new_weight
                            dp_path[i][k+1] = dp_path[j][k] + [idx]
            # update global best
            for k in range(1, 5):
                if dp_weight[i][k] > best_weight[k]:
                    best_weight[k] = dp_weight[i][k]
                    best_path[k] = dp_path[i][k]
        # choose best among 1..4 intervals
        best_k = 1
        for k in range(2, 5):
            if best_weight[k] > best_weight[best_k]:
                best_k = k
            elif best_weight[k] == best_weight[best_k] and len(best_path[k]) < len(best_path[best_k]):
                best_k = k
        return sorted(best_path[best_k])
