class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        from bisect import bisect_left
        n = len(intervals)
        # add original indices
        intervals = [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)]
        # sort by start
        intervals.sort(key=lambda x: x[0])
        starts = [x[0] for x in intervals]
        # precompute next non-overlapping index
        nxt = [0]*n
        for i, (l, r, w, idx) in enumerate(intervals):
            nxt[i] = bisect_left(starts, r+1)
        from functools import lru_cache
        @lru_cache(None)
        def dp(i, k):
            if i==n or k==0:
                return (0, ())
            # skip current
            best = dp(i+1, k)
            # take current
            w, rest = dp(nxt[i], k-1)
            w += intervals[i][2]
            take = (w, (intervals[i][3],)+rest)
            if w > best[0]:
                best = take
            elif w == best[0]:
                if take[1] < best[1]:
                    best = take
            return best
        best_weight, best_idxs = dp(0, 4)
        return list(best_idxs)
