        for i in range(self.N - 1, 0, -1):
            self.minv[i] = min(self.minv[2 * i], self.minv[2 * i + 1])

    def _apply(self, idx, val):
        self.minv[idx] = val
        self.lazy[idx] = val

    def _push(self, idx):
        if self.lazy[idx] is not None:
            self._apply(idx << 1, self.lazy[idx])
            self._apply(idx << 1 | 1, self.lazy[idx])
            self.lazy[idx] = None

    def range_min(self, l, r, idx=1, lx=0, rx=None):
        if rx is None:
            rx = self.N
        if r <= lx or rx <= l:
            return 1 << 60
        if l <= lx and rx <= r:
            return self.minv[idx]
