        self._update(x * 2, l, mid, ql, qr, val)
        self._update(x * 2 + 1, mid + 1, r, ql, qr, val)
        self.minv[x] = min(self.minv[x * 2], self.minv[x * 2 + 1])

    def update(self, l, r, val):
        self._update(1, 1, self.size, l, r, val)

    def _query(self, x, l, r, ql, qr):
        if ql > r or qr < l:
            return 10**18
        if ql <= l and r <= qr:
            return self.minv[x]
        self._push(x)
        mid = (l + r) // 2
        return min(self._query(x * 2, l, mid, ql, qr),
                   self._query(x * 2 + 1, mid + 1, r, ql, qr))

    def query(self, l, r):
        return self._query(1, 1, self.size, l, r)

def solve():
    input = sys.stdin.readline
    H, W, N = map(int, input().split())
    bars = [tuple(map(int, input().split())) for _ in range(N)]
    seg = SegTree(W, 1)  # lowest free row for each column
    out = []
    for R, C, L in bars:
        l, r = C, C + L - 1
        min_free = seg.query(l, r)
        top = min_free - L
        if top < 1:
            top = 1
        out.append(str(top))
        seg.update(l, r, top + L)
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

