from collections import defaultdict

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # state[sum][product] = set of parities (next index parity)
        state: Dict[int, Dict[int, Set[int]]] = defaultdict(lambda: defaultdict(set))

        for num in nums:
            # copy current state to avoid in-place updates during iteration
            cur_state = [ (s, p, par) for s, mp in state.items() for p, par_set in mp.items() for par in par_set ]
            # start new subsequence with num
            if num <= limit:
                state[num][num].add(1)  # next parity will be 1 (odd index)
            # extend existing subsequences
            for s, p, par in cur_state:
                # compute new sum
                new_sum = s + num if par == 0 else s - num
                new_par = 1 - par
                new_prod = p * num
                if new_prod > limit:
                    continue
                state[new_sum][new_prod].add(new_par)

        # find max product for sum==k
        best = -1
        if k in state:
            for prod in state[k]:
                if prod <= limit:
                    best = max(best, prod)
        return best
