import sys
from collections import defaultdict

MOD = 998244353

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    S = data[1]

    # Build pair mapping and children list
    stack = []
    pair = {}
    children = defaultdict(list)
    for i, ch in enumerate(S):
        if ch == '(':
            stack.append(i)
        else:
            l = stack.pop()
            pair[l] = i
            pair[i] = l
            if stack:
                children[stack[-1]].append(l)

    # Determine top-level pair openings
    top_levels = []
    depth = 0
    for i, ch in enumerate(S):
        if ch == '(':
            if depth == 0:
                top_levels.append(i)
            depth += 1
        else:
            depth -= 1

    sys.setrecursionlimit(10000)
    memo_hash = {}
    def dfs(u):
        if u in memo_hash:
            return memo_hash[u]
        chs = children.get(u, [])
        child_hashes = []
        for c in chs:
            child_hashes.append(dfs(c))
        child_hashes.sort()
        h = tuple(child_hashes)
        memo_hash[u] = h
        return h

    # Precompute factorials and inverse factorials
    fact = [1] * (N + 1)
    for i in range(2, N + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact = [1] * (N + 1)
    inv_fact[N] = pow(fact[N], MOD-2, MOD)
    for i in range(N, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD

    # Recursive computation of number of distinct strings for a node
    def calc(u):
        chs = children.get(u, [])
        cnt = defaultdict(int)
        prod = 1
        for c in chs:
            prod = prod * calc(c) % MOD
            cnt[memo_hash[c]] += 1
        k = len(chs)
        prod = prod * fact[k] % MOD
        for v in cnt.values():
            prod = prod * inv_fact[v] % MOD
        return prod

    # Compute for dummy root (top-level pairs)
    cnt = defaultdict(int)
    prod = 1
    for t in top_levels:
        prod = prod * calc(t) % MOD
        cnt[memo_hash[t]] += 1
    k = len(top_levels)
    prod = prod * fact[k] % MOD
    for v in cnt.values():
        prod = prod * inv_fact[v] % MOD

    print(prod % MOD)

if __name__ == "__main__":
    solve()

