class Solution:
    def countComponents(self, nums: list[int], threshold: int) -> int:
        n = len(nums)
        # All numbers are unique
        # Build DSU
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        # Keep only numbers <= threshold because lcm of two numbers > threshold
        # is always > threshold
        small_idx = [i for i, v in enumerate(nums) if v <= threshold]
        if not small_idx:
            return n

        small_vals = [nums[i] for i in small_idx]
        m = len(small_vals)

        # Precompute gcd for speed
        import math
        for i in range(m):
            vi = small_vals[i]
            for j in range(i + 1, m):
                vj = small_vals[j]
                if vi > vj:
                    vi, vj = vj, vi
                # Quick rejection: if vi * vj > threshold * vi, then lcm > threshold
                if vi * vj > threshold * vi:
                    continue
                l = vi * vj // math.gcd(vi, vj)
                if l <= threshold:
                    union(small_idx[i], small_idx[j])

        # Count components
        seen = set()
        for i in range(n):
            seen.add(find(i))
        return len(seen)
